with with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '30' minute then 1 else 0 end as is_new_session from device_readings), sessionized as (select id, device_code, reading_ts, firmware, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from with_gaps) select device_code, date_trunc('hour', reading_ts) as hour_window, case when burst_id >= 8 then 'HIGH' else 'LOW' end as burst_id_tier, min(reading_ts) as started_at, max(reading_ts) as last_reading_ts, avg(burst_id) as avg_burst_id, count(*) filter (where device_code = 'DV-02') as dv_02_rows, min(reading_ts) as started_at_2 from sessionized group by device_code, date_trunc('hour', reading_ts), case when burst_id >= 8 then 'HIGH' else 'LOW' end having dv_02_rows > 1 order by avg_burst_id desc
